//! Per-client ChaCha20-Poly1305 "noise" transport wrap.
//!
//! Wire format: `CMNK` || nonce(12) || ciphertext||tag
//! Key: 32 random bytes generated by the client at enroll and exchanged
//! with the server (stored server-side for unwrap).

use chacha20poly1305::{
    ChaCha20Poly1305, Nonce,
    aead::{Aead, KeyInit},
};
use rand::RngCore;
use sha2::{Digest, Sha256};

pub const MAGIC: &[u8; 4] = b"CMNK";
pub const KEY_LEN: usize = 32;
pub const NONCE_LEN: usize = 12;

pub fn fingerprint_key(key: &[u8]) -> String {
    hex::encode(Sha256::digest(key))
}

pub fn validate_noise_key_hex(hex_key: &str) -> Result<Vec<u8>, String> {
    let bytes = hex::decode(hex_key.trim()).map_err(|e| format!("noise_key hex: {e}"))?;
    if bytes.len() != KEY_LEN {
        return Err(format!("noise_key must be {KEY_LEN} bytes"));
    }
    Ok(bytes)
}

#[allow(dead_code)] // used by clients; kept here for round-trip checks / future server paths
pub fn seal(plaintext: &[u8], key: &[u8]) -> Result<Vec<u8>, String> {
    if key.len() != KEY_LEN {
        return Err("noise key length".into());
    }
    let cipher = ChaCha20Poly1305::new_from_slice(key).map_err(|e| e.to_string())?;
    let mut nonce_bytes = [0u8; NONCE_LEN];
    rand::thread_rng().fill_bytes(&mut nonce_bytes);
    let nonce = Nonce::from_slice(&nonce_bytes);
    let ct = cipher
        .encrypt(nonce, plaintext)
        .map_err(|e| format!("noise seal: {e}"))?;
    let mut out = Vec::with_capacity(MAGIC.len() + NONCE_LEN + ct.len());
    out.extend_from_slice(MAGIC);
    out.extend_from_slice(&nonce_bytes);
    out.extend_from_slice(&ct);
    Ok(out)
}

pub fn open(blob: &[u8], key: &[u8]) -> Result<Vec<u8>, String> {
    if key.len() != KEY_LEN {
        return Err("noise key length".into());
    }
    if blob.len() < MAGIC.len() + NONCE_LEN + 16 {
        return Err("noise blob too short".into());
    }
    if &blob[..4] != MAGIC {
        return Err("not a CMNK blob".into());
    }
    let nonce = Nonce::from_slice(&blob[4..4 + NONCE_LEN]);
    let ct = &blob[4 + NONCE_LEN..];
    let cipher = ChaCha20Poly1305::new_from_slice(key).map_err(|e| e.to_string())?;
    cipher
        .decrypt(nonce, ct)
        .map_err(|_| "noise open failed (bad key or corrupt blob)".into())
}

pub fn is_cmnk(blob: &[u8]) -> bool {
    blob.len() >= 4 && &blob[..4] == MAGIC
}
